/* Audit screen parity based on visible authorized-demo measurements. */
let auditModuleFilter='',auditActionFilter='',auditDateFilter='';
function auditLocalDay(value){let date=new Date(value);return Number.isFinite(date.getTime())?new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(date):''}
function auditActionGroup(action){let text=String(action||'').toLowerCase();return /login|session|auth/.test(text)?'login':/delete|remove|purge|archive/.test(text)?'delete':/backup|export/.test(text)?'backup':/create|add/.test(text)?'create':/update|edit/.test(text)?'update':'other'}
function auditFilteredRows(){let now=today(),date=new Date(now+'T00:00:00Z'),yesterday=new Date(date.getTime()-86400000).toISOString().slice(0,10),week=new Date(date.getTime()-6*86400000).toISOString().slice(0,10);return db.audit.filter(matches).filter(a=>!auditModuleFilter||a.module===auditModuleFilter).filter(a=>!auditActionFilter||auditActionGroup(a.action)===auditActionFilter).filter(a=>{let day=auditLocalDay(a.date);return !auditDateFilter||auditDateFilter==='today'&&day===now||auditDateFilter==='yesterday'&&day===yesterday||auditDateFilter==='week'&&day>=week&&day<=now||auditDateFilter==='month'&&day.startsWith(now.slice(0,7))&&day<=now})}
function auditDisplayDate(value){let d=new Date(value);return Number.isFinite(d.getTime())?d.toLocaleString('en-IN',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:true}):'—'}
function auditLogTable(rows){return table(['#','Date & Time','User / Role','Module','Action','Event Description & Details','Status'],rows.map((a,i)=>[i+1,esc(auditDisplayDate(a.date)),esc(a.user||'—')+'<small>'+esc(a.role||'Admin')+'</small>',badge(a.module||'—'),badge(a.action||'—'),esc(a.detail||'—'),badge(a.status||'—')]))}
auditPage=function(){let rows=auditFilteredRows(),cards=[['Total Activity Logs',db.audit.length,'list','neutral'],["Today's Activities",db.audit.filter(a=>auditLocalDay(a.date)===today()).length,'calendar','blue'],['Logins & Security',db.audit.filter(a=>auditActionGroup(a.action)==='login').length,'users','green'],['Critical Events',db.audit.filter(a=>auditActionGroup(a.action)==='delete'||/fail|error|denied/i.test(a.status||'')).length,'shield','red']];return '<section class="auditReviewPanel"><div class="auditIntro"><h2>'+icon('clipboard')+' System Audit & Activity Logs</h2><p>Comprehensive chronological record of system events, invoices, inventory edits & changes</p><div class="auditButtons"><button class="btn auditExport" data-action="export">'+icon('file')+' Export Excel</button><button class="btn auditPrint" id="printAuditLogs">'+icon('print')+' Print Logs</button><button class="btn auditClear" id="clearAuditLogs">'+icon('trash')+' Clear Logs</button>'+((db.auditArchives||[]).length?'<button class="btn secondary" id="restoreAuditLogs">Restore Cleared Logs</button>':'')+'</div></div><div class="auditCards">'+cards.map(([title,value,symbol,color])=>'<div class="auditCard '+color+'"><span class="auditCardIcon">'+icon(symbol)+'</span><div><small>'+esc(title)+'</small><strong>'+value+'</strong></div></div>').join('')+'</div><div class="auditFilters"><input id="search" class="search" aria-label="Search audit logs" placeholder="Search user, action, details, ID..." value="'+esc(search)+'"><select id="auditModuleFilter" aria-label="Filter audit module"><option value="">All Modules</option>'+opts([...new Set(db.audit.map(a=>a.module).filter(Boolean))].sort(),auditModuleFilter)+'</select><select id="auditActionFilter" aria-label="Filter audit action"><option value="">All Action Types</option>'+opts([{value:'create',label:'Create / Add'},{value:'update',label:'Update / Edit'},{value:'delete',label:'Delete / Remove'},{value:'login',label:'Login / Session'},{value:'backup',label:'Backup / Export'},{value:'other',label:'Other Actions'}],auditActionFilter)+'</select><select id="auditDateFilter" aria-label="Filter audit date"><option value="">All Time</option>'+opts([{value:'today',label:'Today'},{value:'yesterday',label:'Yesterday'},{value:'week',label:'Last 7 Days'},{value:'month',label:'This Month'}],auditDateFilter)+'</select><button class="btn secondary" id="resetAuditFilters">Reset</button></div>'+auditLogTable(rows)+'<div class="auditFooter"><span>Showing '+rows.length+' of '+db.audit.length+' activity logs</span><span>Activity Logging Active</span></div></section>'};
function archiveAuditLogs(){if(!db.audit.length)return false;let before=structuredClone(db);db.auditArchives=db.auditArchives||[];db.auditArchives.push({id:'AUDIT-ARCHIVE-'+Date.now(),date:new Date().toISOString(),logs:structuredClone(db.audit)});db.audit=[];audit('Archive','Audit logs cleared from active view; recoverable from archived logs');if(save('Audit logs archived')===false){db=before;return false}return true}
function restoreLastAuditArchive(){let before=structuredClone(db),archive=db.auditArchives?.pop();if(!archive)return false;let ids=new Set(db.audit.map(a=>a.id));db.audit.push(...archive.logs.filter(a=>!ids.has(a.id)));db.audit.sort((a,b)=>new Date(b.date)-new Date(a.date));audit('Restore','Restored archived audit logs');if(save('Audit logs restored')===false){db=before;return false}return true}
const renderBeforeAuditParity=render;
render=function(){renderBeforeAuditParity();if(page!=='audit')return;for(let [selector,set]of [['#auditModuleFilter',v=>auditModuleFilter=v],['#auditActionFilter',v=>auditActionFilter=v],['#auditDateFilter',v=>auditDateFilter=v]])if($(selector))$(selector).onchange=e=>{set(e.target.value);render()};if($('#resetAuditFilters'))$('#resetAuditFilters').onclick=()=>{auditModuleFilter='';auditActionFilter='';auditDateFilter='';search='';render()};if($('#printAuditLogs'))$('#printAuditLogs').onclick=()=>openModal('Print Audit Logs','<div class="invoice"><h2>'+esc(db.settings.name)+' — Audit Logs</h2><p>'+esc(today())+'</p>'+auditLogTable(auditFilteredRows())+'</div><div class="formactions">'+btn('Close','cancel','secondary')+btn('Print / Save PDF','print','','print')+'</div>');if($('#clearAuditLogs'))$('#clearAuditLogs').onclick=()=>{openModal('Clear Audit Logs','<div class="formbody"><p>Move the '+db.audit.length+' active audit logs into a recoverable archive? You can restore them using Restore Cleared Logs.</p></div><div class="formactions">'+btn('Cancel','cancel','secondary')+'<button class="btn danger" id="confirmArchiveAudit">Archive & Clear</button></div>');$('#confirmArchiveAudit').onclick=()=>{if(archiveAuditLogs()){closeModal();render()}}};if($('#restoreAuditLogs'))$('#restoreAuditLogs').onclick=()=>{if(restoreLastAuditArchive())render()}};
render();
